      $('#pvHead').textContent = p.name + ' — ' + p.headline; $('#pvIntro').textContent = p.intro;
      $('#pvFacts').innerHTML = p.facts.map(function(f){ return '<li>'+esc(f)+'</li>'; }).join('');
