  function openModal(){ lastFocus = document.activeElement; modal.hidden = false; document.body.style.overflow = 'hidden'; $('#mX').focus(); }
  function closeModal(){ modal.hidden = true; mMedia.innerHTML = ''; document.body.style.overflow = ''; mIn.classList.remove('m-only'); curWork = -1; if (lastFocus && lastFocus.isConnected) lastFocus.focus(); }
  function mediaFor(v){
    if (!v) return '<div class="phbox">영상 추후 공개</div>';
    var yt = v.match(/(?:youtu\.be\/|v=|embed\/)([\w-]{11})/);
    if (yt) return '<iframe src="https://www.youtube-nocookie.com/embed/'+yt[1]+'?autoplay=1&rel=0" allow="autoplay; encrypted-media; fullscreen" allowfullscreen title="작품 영상"></iframe>';
    return '<video src="'+esc(v)+'" controls autoplay playsinline></video>';
  }
