  function moveWork(n){ var vis = $$('.wk').filter(function(el){ return !el.hidden; }).map(function(el){ return +el.dataset.i; }); if (!vis.length) return; var p = vis.indexOf(curWork); openWork(vis[(p + n + vis.length) % vis.length]); }
